    pattern = "A..B..C"
    m = len(pattern)

    def can_window(i):
        # returns min ops for window starting at i, or None if impossible
        ops = 0
        for j in range(m):
            need = pattern[j]
            ch = s[i + j]
            if need == 'A':
                if ch == 'A':
                    pass
                elif ch == '.':
                    ops += 1
                else:
                    return None
            elif need == 'B':
                if ch == 'B':
                    pass
                elif ch == '.':
                    ops += 1
                else:
                    return None
            elif need == 'C':
                if ch == 'C':
                    pass
                elif ch == '.':
                    ops += 1
                else:
                    return None
            else:  # pattern wildcard '.'
                # wildcard can match any character, including '.'
