```python
from typing import List

class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        ans = []
        if not grid:
            return ans

        m = len(grid)
        n = len(grid[0])

        for r in range(m):
            cols = range(n) if r % 2 == 0 else range(n - 1, -1, -1)
            for c in cols:
                v = grid[r][c]
                if v != 0:
                    ans.append(v)

        return ans
```

