class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        parent = list(range(n))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra != rb:
                parent[ra] = rb

        sets = [set(p) for p in properties]

        for i in range(n):
            si = sets[i]
            for j in range(i + 1, n):
                if len(si & sets[j]) >= k:
                    union(i, j)

        return len({find(i) for i in range(n)})
```

