from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # state: (alternating_sum, parity) -> max product <= limit
        # parity 0 means the next chosen element is added with a '+' sign
        dp = {(0, 0): 1}

        for x in nums:
            ndp = {}

            # do not take x
            for key, prod in dp.items():
                ndp[key] = max(ndp.get(key, 0), prod)

            # take x
            for (s, p), prod in dp.items():
                if p == 0:
                    ns = s + x
                    np = 1
                else:
                    ns = s - x
                    np = 0

                nprod = prod * x
                if nprod > limit:
                    continue

                key = (ns, np)
                if nprod > ndp.get(key, 0):
                    ndp[key] = nprod

            dp = ndp

        ans = -1
        for (s, p), prod in dp.items():
            if s == k and prod > ans:
                ans = prod
        return ans
```

