from typing import List

class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        if k > n:
            return -1
        if k == 0:
            return 0 if n == 0 else -1

        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + cost[i]

        # Sparse table for O(1) range maximum.
        LOG = max(1, (n).bit_length())
        st = [[0] * n for _ in range(LOG)]
        for i in range(n):
            st[0][i] = nums[i]
        j = 1
        while (1 << j) <= n:
            for i in range(n - (1 << j) + 1):
                st[j][i] = max(st[j - 1][i], st[j - 1][i + (1 << (j - 1))])
            j += 1

        def range_max(l: int, r: int) -> int:
            # inclusive [l, r]
            length = r - l + 1
            m = length.bit_length() - 1
            return max(st[m][l], st[m][r - (1 << m) + 1])

        INF = float('inf')
        dp = [[INF] * (n + 1) for _ in range(k + 1)]
        dp[0][0] = 0

        for i in range(1, n + 1):
            for p in range(1, k + 1):
                best = INF
                for j in range(1, i + 1):
                    prev = dp[p - 1][j - 1]
                    if prev == INF:
                        continue
                    seg_cost = prefix[i] - prefix[j - 1]
                    seg_max = range_max(j - 1, i - 1)
                    val = prev + seg_max * seg_cost
                    if val < best:
                        best = val
                dp[p][i] = best

        return int(dp[k][n])
```

