```python
from typing import List
from itertools import combinations

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if k <= 0 or k > n:
            return []

        def lcp_len(indices):
            if not indices:
                return 0
            prefix = words[indices[0]]
            for idx in indices[1:]:
                s = words[idx]
                i = 0
                m = min(len(prefix), len(s))
                while i < m and prefix[i] == s[i]:
                    i += 1
                prefix = prefix[:i]
                if not prefix:
                    return 0
            return len(prefix)

        ans = set()
        for subset in combinations(range(n), k):
            ans.add(lcp_len(subset))
        return sorted(ans)
